import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

public class FilterRulesTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        Predicate<String> notEmpty = s -> !s.isEmpty();
        Predicate<String> shortWord = s -> s.length() <= 4;
        List<String> words = List.of("", "fig", "banana");

        checkCall("allOf keeps values every rule accepts", "[fig]",
                () -> FilterRules.keep(words, FilterRules.allOf(List.of(notEmpty, shortWord))).toString());
        checkCall("anyOf keeps values one rule accepts", "[, banana]",
                () -> FilterRules.keep(words, FilterRules.anyOf(
                        List.<Predicate<String>>of(s -> s.isEmpty(), s -> s.length() > 5))).toString());
        checkCall("not flips a rule", "[]",
                () -> FilterRules.keep(List.of("fig", "kiwi"), FilterRules.not(notEmpty)).toString());
        checkCall("an empty allOf accepts everything", "[, fig, banana]",
                () -> FilterRules.keep(words, FilterRules.allOf(new ArrayList<Predicate<String>>())).toString());
        checkCall("an empty anyOf accepts nothing", "[]",
                () -> FilterRules.keep(words, FilterRules.anyOf(new ArrayList<Predicate<String>>())).toString());
        checkCall("keep does not modify its input", "[, fig, banana]", () -> {
            FilterRules.keep(words, notEmpty);
            return words.toString();
        });
        checkCall("rules work on numbers too", "[4, 6]",
                () -> FilterRules.keep(List.of(3, 4, 6, 9),
                        FilterRules.allOf(List.<Predicate<Integer>>of(n -> n % 2 == 0, n -> n > 3))).toString());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

