import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

public class FilterRules {

    public static <T> Predicate<T> allOf(List<Predicate<T>> rules) {
        return value -> {
            for (Predicate<T> rule : rules) {
                if (!rule.test(value)) {
                    return false;
                }
            }
            return true;
        };
    }

    public static <T> Predicate<T> anyOf(List<Predicate<T>> rules) {
        return value -> {
            for (Predicate<T> rule : rules) {
                if (rule.test(value)) {
                    return true;
                }
            }
            return false;
        };
    }

    public static <T> Predicate<T> not(Predicate<T> rule) {
        return value -> !rule.test(value);
    }

    public static <T> List<T> keep(List<T> items, Predicate<T> rule) {
        List<T> kept = new ArrayList<>();
        for (T item : items) {
            if (rule.test(item)) {
                kept.add(item);
            }
        }
        return kept;
    }
}
